'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { parse, compare, satisfies, compileRange } = require('./src/semver');

const versions = (...values) => Object.fromEntries(values.map(value => [value, {}]));

test('numeric ordering at every component and first-found FIFO selection', () => {
  for (const [older, newer] of [['9.0.0', '10.0.0'], ['1.9.0', '1.10.0'], ['1.0.9', '1.0.10']]) {
    assert.deepEqual(resolve({ a: versions(older, newer) }, { a: '*' }), { a: newer });
  }
  const registry = {
    a: { '2.0.0': { b: '1.0.0' }, '1.0.0': { b: '2.0.0' } },
    b: versions('1.0.0', '2.0.0'),
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), { a: '2.0.0', b: '1.0.0' });
  assert.deepEqual(resolve(registry, { b: '*', a: '*' }), { b: '2.0.0', a: '1.0.0' });
  assert.deepEqual(resolve({
    a: { '1.0.0': { c: '*' } },
    b: { '1.0.0': { c: '<2.0.0' } },
    c: versions('1.0.0', '2.0.0'),
  }, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0', c: '1.0.0' });
});

test('rollback removes dependencies, constraints, selections, and partial appends', () => {
  assert.deepEqual(resolve({ a: { '2.0.0': { missing: '*' }, '1.0.0': {} } }, { a: '*' }), { a: '1.0.0' });
  assert.deepEqual(resolve({
    a: { '2.0.0': { b: '2.0.0' }, '1.0.0': { b: '1.0.0' } },
    b: { '2.0.0': { ghost: '*' }, '1.0.0': {} },
  }, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
  assert.deepEqual(resolve({
    a: { '2.0.0': { orphan: '*', a: '<2.0.0', missing: '*' }, '1.0.0': {} },
    orphan: versions('1.0.0'),
  }, { a: '*' }), { a: '1.0.0' });
  assert.deepEqual(resolve({
    a: { '2.0.0': { b: '*', c: '*' }, '1.0.0': {} },
    b: { '2.0.0': { a: '<2.0.0' }, '1.0.0': { c: '<2.0.0' } },
    c: versions('1.0.0', '2.0.0'),
  }, { a: '*' }), { a: '2.0.0', b: '1.0.0', c: '1.0.0' });
  assert.equal(resolve({ a: { '1.0.0': { a: '>1.0.0' } } }, { a: '*' }), null);
  assert.equal(resolve({}, { missing: '*' }), null);
  assert.equal(resolve({ a: {} }, { a: '*' }), null);
});

test('cycles expand once and long chains resolve and unwind iteratively', () => {
  assert.deepEqual(resolve({ a: { '1.0.0': { a: '*' } } }, { a: '*' }), { a: '1.0.0' });
  assert.deepEqual(resolve({
    a: { '1.0.0': { b: '*' } }, b: { '1.0.0': { a: '*' } },
  }, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
  const count = 20000;
  const registry = {};
  const expected = {};
  for (let i = 0; i < count; i++) {
    registry['p' + i] = { '1.0.0': { ['p' + ((i + 1) % count)]: '*' } };
    expected['p' + i] = '1.0.0';
  }
  assert.deepEqual(resolve(registry, { p0: '*' }), expected);
  registry.start = { '2.0.0': { p0: '*' }, '1.0.0': {} };
  registry['p' + (count - 1)] = { '1.0.0': { absent: '*' } };
  assert.deepEqual(resolve(registry, { start: '*' }), { start: '1.0.0' });
});

test('selected conflicts are checked before exploring unrelated choices', () => {
  const registry = {
    a: versions('1.0.0', '2.0.0'),
    b: { '1.0.0': { a: '1.0.0' } },
  };
  const root = { a: '*', b: '*' };
  const expected = { a: '1.0.0', b: '1.0.0' };
  for (let i = 0; i < 60; i++) {
    registry['noise' + i] = versions('1.0.0', '2.0.0');
    root['noise' + i] = '*';
    expected['noise' + i] = '2.0.0';
  }
  assert.deepEqual(resolve(registry, root), expected);
});

test('eager validation, plain maps, own keys, special names, and immutable inputs', () => {
  for (const bad of [null, [], 1, 'x', new Date(), Object.create({})]) {
    assert.throws(() => resolve(bad, {}), TypeError);
    assert.throws(() => resolve({}, bad), TypeError);
    assert.throws(() => resolve({ unused: bad }, {}), TypeError);
    assert.throws(() => resolve({ unused: { '1.0.0': bad } }, {}), TypeError);
  }
  assert.throws(() => resolve({ unused: { '01.0.0': {} } }, {}), TypeError);
  assert.throws(() => resolve({ unused: { '1.0.0': { other: 'bogus' } } }, {}), TypeError);
  assert.throws(() => resolve({}, { a: '' }), TypeError);
  const registry = Object.create(null);
  const root = Object.create(null);
  const expected = {};
  for (const name of ['__proto__', 'constructor', 'toString']) {
    registry[name] = Object.freeze({ '1.0.0': Object.freeze({}) });
    root[name] = '*';
    Object.defineProperty(expected, name, { value: '1.0.0', enumerable: true, configurable: true, writable: true });
  }
  Object.defineProperty(registry, 'ignored', { value: null });
  registry[Symbol('ignored')] = null;
  Object.freeze(registry);
  Object.freeze(root);
  const result = resolve(registry, root);
  assert.equal(Object.getPrototypeOf(result), Object.prototype);
  assert.deepEqual(result, expected);
  assert.deepEqual(resolve(registry, {}), {});
});

test('semver canonical validation, numeric comparison, and range boundaries', () => {
  assert.deepEqual(parse('9007199254740991.0.12'), [9007199254740991, 0, 12]);
  for (const bad of [null, 1, '', '1.0', '01.0.0', '1.00.0', '1.0.00', '-1.0.0', '1.0.0-beta', '1.0.0+build', ' 1.0.0', '1.0.0\n', '9007199254740992.0.0']) {
    assert.throws(() => parse(bad), TypeError);
