// Small copied-state DFS oracle: deliberately independent of the production trail.
function reference(registry, root) {
  function visit(selected, queue, cursor, constraints) {
    for (const [name, ranges] of Object.entries(constraints)) {
      if (Object.hasOwn(selected, name) && !ranges.every(range => satisfies(selected[name], range))) return null;
    }
    if (cursor === queue.length) return selected;
    const name = queue[cursor];
    if (Object.hasOwn(selected, name)) return visit(selected, queue, cursor + 1, constraints);
    const candidates = Object.keys(registry[name] || {}).sort((a, b) => compare(b, a));
    for (const version of candidates) {
      if (!constraints[name].every(range => satisfies(version, range))) continue;
      const nextQueue = queue.slice();
      const nextConstraints = Object.fromEntries(Object.entries(constraints).map(([key, value]) => [key, value.slice()]));
      for (const [dep, range] of Object.entries(registry[name][version])) {
        (nextConstraints[dep] ||= []).push(range);
        nextQueue.push(dep);
      }
      const result = visit({ ...selected, [name]: version }, nextQueue, cursor + 1, nextConstraints);
      if (result !== null) return result;
    }
    return null;
  }
  return visit({}, Object.keys(root), 0, Object.fromEntries(Object.entries(root).map(([name, range]) => [name, [range]])));
}

test('first-found assignment matches copied-state DFS across deterministic cyclic registries', () => {
  let state = 123456789;
  const random = limit => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state % limit;
  };
  const names = ['a', 'b', 'c', 'd'];
  const ranges = ['*', '1.0.0', '2.0.0', '>=2.0.0', '<2.0.0', '>3.0.0'];
  for (let trial = 0; trial < 1000; trial++) {
    const registry = {};
    for (const name of names) {
      registry[name] = {};
      for (const version of ['1.0.0', '2.0.0', '3.0.0']) {
