          deps[random(10) === 0 ? 'missing' : names[random(names.length)]] = ranges[random(ranges.length)];
        }
        registry[name][version] = deps;
      }
    }
    const root = {};
    for (let i = 0, count = random(5); i < count; i++) root[names[random(names.length)]] = ranges[random(ranges.length)];
    assert.deepEqual(resolve(registry, root), reference(registry, root), 'trial ' + trial);
  }
});

